update pages set contenu = '{"gabarit":"fiche","chapeau":"En 2025, AUTOLIV a sollicité Migen pour renforcer son équipe technique. Un technicien de maintenance polyvalent a été affecté au site, pour contribuer au maintien du parc machines.","fiche":[],"contexte":"**Un poste de maintenance vacant ne se voit pas tout de suite.** Il se voit le jour où le parc machines commence à décrocher.\nRecruter un technicien prend des mois. Pendant ce temps, l''équipe en place absorbe la charge, le préventif saute et le correctif s''accumule. Le besoin posé par le site :\n**Maintenir le parc machines** sans créer un poste dans l''urgence.\n**Soutenir l''équipe existante** sans désorganiser son fonctionnement.\n**Disposer d''un profil opérationnel tout de suite**, pas d''un renfort à former.","intervention":"**Un technicien dédié, pas un dépanneur de passage** : Un profil polyvalent est affecté au site et intégré aux équipes internes d''AUTOLIV.\n**Une présence continue** : Le technicien travaille sur les horaires et les priorités du site, aux côtés des équipes en place.\n**Un renfort sans réorganisation** : L''équipe maintenance garde son fonctionnement. Le renfort s''ajoute, il ne remplace rien.\n**Un pilotage assuré par Migen** : Le suivi de la prestation reste de notre côté. Le client garde son temps pour la production.\nCe que couvre le technicien sur site : la participation aux actions de maintenance, la continuité de fonctionnement des équipements et l''appui technique aux équipes, sur le terrain.","resultats":[]}'::jsonb where path = '/preuves/autoliv/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"AUTOLIV"},{"libelle":"Secteur","valeur":"Industrie automobile"},{"libelle":"Année","valeur":"2025"},{"libelle":"Effectif Migen","valeur":"1 technicien de maintenance polyvalent"},{"libelle":"Périmètre","valeur":"Maintien opérationnel du parc machines"},{"libelle":"Organisation","valeur":"Technicien intégré aux équipes internes, présence continue"},{"libelle":"Pilotage","valeur":"Suivi de mission assuré par Migen"}]'::jsonb) where path = '/preuves/autoliv/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Une approche directe, sur le terrain","libelle":"Pas de surcouche de gestion entre le besoin et le technicien."},{"valeur":"Le bon profil au bon moment","libelle":"Les équipements industriels restent opérationnels."},{"valeur":"Une continuité de fonctionnement","libelle":"Le parc machines est tenu, sans création de poste."}]'::jsonb) where path = '/preuves/autoliv/';
